def _ui(observation: Any) -> dict[str, Any]:
    nodes = getattr(observation, "ui_nodes", []) or []
    texts = [str(n.get("text") or "") for n in nodes if isinstance(n, Mapping)]
    values = {}
    for label, expected_value in RULESET_SPEC["final_ui"]["values"].items():
        wanted = f"{label} {expected_value}"
        if texts.count(wanted) == 1:
            values[label] = expected_value
    return {"foreground_app": getattr(observation, "foreground_app", ""), "foreground_window": getattr(observation, "foreground_window", ""), "source_name": "pe1_headscarf_selfie.png" if texts.count("pe1_headscarf_selfie.png") >= 1 else None, "active_group": "Edit" if any(n.get("selector") == "Edit" and n.get("type") == "textcontrol" for n in nodes if isinstance(n, Mapping)) else None, "values": values}


